    """Parse a human amount like "1,234.56" into an integer number of cents."""
    cleaned = str(text).strip().replace(",", "").replace("$", "")
    if not cleaned:
        raise ValueError("empty amount")
    negative = cleaned.startswith("-")
    if negative:
        cleaned = cleaned[1:]
    if "." in cleaned:
        whole, _, frac = cleaned.partition(".")
        frac = (frac + "00")[:2]
    else:
